55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Insurance values are independent of base premiums and of any premium modifier. */
68	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const DEDUCTIBLE_PER_DAMAGE = 100;
78	const CAP_MULTIPLIER = 2;
79	const CLAIM_HALVING_THRESHOLD = 8;
80	const CLAIM_HALVING_RATE = 0.5;
81	
82	const COMPONENT_TYPES = ["rune", "moonstone"];
83	const BLOCK_SIZE = 3;
84	const BLOCK_BASE_PREMIUM = 60;
85	const CURSE_SURCHARGE_RATE = 0.5;
86	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
87	const HIGH_ENCHANTMENT_THRESHOLD = 5;
88	const LOYALTY_DISCOUNT_RATE = 0.2;
89	const LOYALTY_YEARS_THRESHOLD = 2;
90	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
91	
92	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
93	
94	/** Premiums round up — in the MHPCO's favour. */
95	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
96	
97	/** Payouts round down — also in the MHPCO's favour. */
98	const roundDownToWholeG = (amount: number): number => Math.floor(amount);
99	
100	const groupByType = (items: Item[]): Map<string, Item[]> => {
101	  const groups = new Map<string, Item[]>();
102	  for (const item of items) {
103	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
104	  }
105	  return groups;
106	};
107	
108	/**
109	 * A type is known only when BOTH tables define it. The tables stay separate
110	 * because pricing and cover are separate concepts that vary independently — the
111	 * block discount and the curse surcharge move premiums without moving the cap.
112	 * But a type defined in one table and not the other is a half-defined type, and
113	 * validating against either table alone would wave it through to become the
114	 * silent NaN this guard exists to prevent. Hence the intersection: a union, or
115	 * either table on its own, would not catch that.
116	 */
117	const KNOWN_ITEM_TYPES = new Set(
118	  Object.keys(BASE_PREMIUM_BY_TYPE).filter((type) => type in INSURANCE_VALUE_BY_TYPE),
119	);
120	
121	const isKnownType = (type: string): boolean => KNOWN_ITEM_TYPES.has(type);
122	
123	/** Guards the lookups, which would otherwise yield undefined and silently poison the arithmetic with NaN. */
124	const assertKnownTypes = (items: Item[]): void => {
125	  for (const item of items) {
126	    if (!isKnownType(item.type)) {
127	      throw new Error(`unknown item type: ${item.type}`);
128	    }
129	  }
130	};
131	
132	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
133	
134	/**
135	 * Components are priced per group of alike items, because a building block of
136	 * exactly 3 alike components earns a special rate. Main items price per item.
137	 */
138	const basePremiumForGroup = (type: string, group: Item[]): number => {
139	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
140	    return BLOCK_BASE_PREMIUM;
141	  }
142	  return sum(group.map(basePremiumForItem));
143	};
144	
145	/** Item-specific surcharges apply to the affected item's own base premium. */
146	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
147	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
148	  {
149	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
150	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
151	  },
152	];
153	
154	const itemSurchargeTotalFor = (item: Item): number =>
155	  sum(
156	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
157	      ({ rate }) => basePremiumForItem(item) * rate,
158	    ),
159	  );
160	
161	/**
162	 * Policy-wide modifiers are rates on the UNMODIFIED policy base premium — not
163	 * on the running total, and not on the item surcharges. Charging 10 % of a
164	 * cursed sword's 150 G rather than of its 100 G base is the mistake this
165	 * indirection exists to prevent.
166	 */
167	const policyModifierTotalFor = (policyBasePremium: number, rates: number[]): number =>
168	  sum(rates.map((rate) => policyBasePremium * rate));
169	
170	/**
171	 * Discounts are negative rates, so the policy modifiers stay a single sum.
172	 *
173	 * The initial assessment surcharge is deliberately NOT in here: it is charged on
174	 * every policy, including a long-standing customer's follow-up contract, so it
175	 * depends on nothing about the customer.
176	 */
177	const customerModifierRatesFor = (customer: Customer): number[] =>
178	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? [-LOYALTY_DISCOUNT_RATE] : [];
179	
180	/** The follow-up discount depends on scenario position, not on the customer. */
181	const policyModifierRatesFor = (customer: Customer, isFollowUpContract: boolean): number[] => [
182	  INITIAL_ASSESSMENT_SURCHARGE_RATE,
183	  ...customerModifierRatesFor(customer),
184	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_RATE] : []),
185	];
186	
187	/**
188	 * The customer and the contract's position in the scenario are context, not
189	 * subject: they are named at the call site so a bare `true` never has to be
190	 * decoded back into "this is a follow-up contract".
191	 */
192	interface PolicyContext {
193	  customer: Customer;
194	  isFollowUpContract: boolean;
195	}
196	
197	const quotePremium = (items: Item[], { customer, isFollowUpContract }: PolicyContext): number => {
198	  assertKnownTypes(items);
199	  const policyBasePremium = sum(
200	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
201	  );
202	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
203	  const policyModifierTotal = policyModifierTotalFor(
204	    policyBasePremium,
205	    policyModifierRatesFor(customer, isFollowUpContract),
206	  );
207	  return roundUpToWholeG(
208	    policyBasePremium + itemSurchargeTotal + policyModifierTotal + PROCESSING_FEE,
209	  );
210	};
211	
212	/** A policy created by a quote step; claims draw down its remaining cap. */
213	interface Policy {
214	  items: Item[];
215	  remainingCap: number;
216	}
217	
218	const openPolicy = (items: Item[]): Policy => {
219	  const insuranceSum = sum(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
220	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
221	};
222	
223	/**
224	 * The amount covered before the deductible, which depends on the damaged item.
225	 *
226	 * Two spec clauses reach this point. The 50 % high-enchantment clause is
227	 * checked first, so it wins when both would apply. Dragon material has NO
228	 * branch of its own: it reimburses in full, which is already the default, so a
229	 * branch for it would return exactly what the fallback returns. No input could
230	 * ever tell the two apart — including a dragon sword at enchantment 9, where
231	 * the halving clause takes precedence anyway. The rule is real but currently
232	 * indistinguishable from the default; give it a branch only once some clause
233	 * makes the default something other than full reimbursement.
234	 */
235	const coveredAmountFor = (damage: Damage, item: Item): number =>
236	  (item.enchantment ?? 0) >= CLAIM_HALVING_THRESHOLD
237	    ? damage.amount * CLAIM_HALVING_RATE
238	    : damage.amount;
239	
240	/**
241	 * A negative amount would yield a negative payout, and since the cap is drawn
242	 * down by the payout, it would INCREASE the remaining cover. Zero is left
243	 * alone: the spec calls out negatives only.
244	 */
245	const assertNonNegativeAmount = (amount: number): void => {
246	  if (amount < 0) {
247	    throw new Error(`damage amount must not be negative: ${amount}`);
248	  }
249	};
250	
251	/** A damage and the specific insured item it was matched against. */
252	interface MatchedDamage {
253	  damage: Damage;
254	  damagedItem: Item;
255	}
256	
257	/**
258	 * Resolves each damage into the DISTINCT insured item it will be paid against,
259	 * rejecting any damage that cannot be resolved.
260	 *
261	 * Validation is not split into a separate pass, because the three rejections are
262	 * one idea — this damage cannot become a payable pair — and one of them is only
263	 * observable mid-walk: exhausting the alike items is what detects too many
264	 * entries, so a pre-pass could not own that check without duplicating the
265	 * consuming match it depends on.
266	 *
267	 * Consuming is what makes the count meaningful: two sword damages against a
268	 * one-sword policy exhaust the swords and the second entry finds nothing, so
269	 * over-claiming is caught by the same mechanism that catches an uninsured type.
270	 *
271	 * Returning pairs rather than a bare item list keeps the correspondence in the
272	 * value: a parallel array would leave the caller re-deriving by index which
273	 * damage each item belongs to, and an index-zip is a correctness invariant no
274	 * type enforces.
275	 *
276	 * `unmatched` is mutated, but it is a private copy that never escapes this
277	 * function, so no caller can observe the mutation.
278	 */
279	const resolveDamages = (damages: Damage[], items: Item[]): MatchedDamage[] => {
280	  const unmatched = [...items];
281	  return damages.map((damage) => {
282	    assertNonNegativeAmount(damage.amount);
283	    const index = unmatched.findIndex((item) => item.type === damage.itemType);
284	    if (index === -1) {
285	      throw new Error(`damaged item is not insured: ${damage.itemType}`);
286	    }
287	    return { damage, damagedItem: unmatched.splice(index, 1)[0] };
288	  });
289	};
290	
291	/** The deductible applies per damage event, after the clause. */
292	const reimbursementFor = ({ damage, damagedItem }: MatchedDamage): number =>
293	  coveredAmountFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
294	
295	/**
296	 * Pure: returns the settlement WITHOUT drawing down the policy. The caller owns
297	 * the policy store and applies `remainingCap`, so a claim's effect on later
298	 * claims is visible at the call site rather than hidden in a shared reference.
299	 */
300	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
301	  const matchedDamages = resolveDamages(incident.damages, policy.items);
302	  const claimed = sum(matchedDamages.map(reimbursementFor));
303	  const payout = roundDownToWholeG(Math.min(claimed, policy.remainingCap));
304	  return { payout, remainingCap: policy.remainingCap - payout };
305	};
306	
307	export const runScenario = (scenario: Scenario): ScenarioResult => {
308	  const results: StepResult[] = [];
309	  /** Keyed by step index, because that is what a claim's `policy` refers to. */
310	  const policiesByStepIndex = new Map<number, Policy>();
311	  let quotesSoFar = 0;
312	
313	  scenario.steps.forEach((step, stepIndex) => {
314	    if (step.op === "quote") {
315	      results.push({
316	        premium: quotePremium(step.items, {
317	          customer: scenario.customer,
318	          isFollowUpContract: quotesSoFar > 0,
319	        }),
320	      });
321	      quotesSoFar += 1;
322	      policiesByStepIndex.set(stepIndex, openPolicy(step.items));
323	      return;
324	    }
325	
326	    /**
327	     * `!` asserts the claim names a policy that exists. Nothing validates that
328	     * yet — a claim against an unknown step index throws an opaque TypeError.
329	     *
330	     * This is the last remaining non-null assertion, and it is deliberate. The
331	     * spec's error list covers an unknown item type in a quote, a damaged item
332	     * not in the policy, a negative amount, and too many damage entries — but
333	     * says nothing about a claim naming a step index that was never quoted. No
334	     * test, active or pending, reaches this line with a missing policy. Giving
335	     * it an error message now would be inventing a requirement the spec has not
336	     * stated; revisit if a test ever demands one.
337	     */
338	    const policy = policiesByStepIndex.get(step.policy)!;
339	    const settlement = settleClaim(policy, step.incident);
340	    /** Successive claims draw down one shared cap. */
341	    policiesByStepIndex.set(step.policy, {
342	      ...policy,
343	      remainingCap: settlement.remainingCap,
344	    });
345	    results.push(settlement);
346	  });
347	
348	  return { results };
349	};
