4	const readStdin = async (): Promise<string> => {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	  return Buffer.concat(chunks).toString("utf8");
10	};
11	
12	const main = async (): Promise<void> => {
13	  const scenario = JSON.parse(await readStdin()) as Scenario;
14	  process.stdout.write(JSON.stringify(runScenario(scenario)));
15	};
16	
17	try {
18	  await main();
19	} catch (error) {
20	  // Only the message: a stack trace would leak absolute paths and interpreter
21	  // internals at someone using this as a JSON-in/JSON-out tool.
22	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
23	  // exitCode rather than exit(1), so buffered writes flush before exiting.
24	  process.exitCode = 1;
25	}
