1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	
4	interface CliResult {
5	  stdout: string;
6	  stderr: string;
7	  exitCode: number;
8	}
9	
10	/**
11	 * Spawns the real CLI so the stdin/stdout contract itself is under test.
12	 *
13	 * Note `execFile`'s `input` option does NOT exist on the async variants — using
14	 * it leaves stdin open and the child waits for EOF forever. The write-then-end
15	 * below is what actually terminates the input stream.
16	 */
17	const runCli = (scenario: unknown): Promise<CliResult> =>
18	  new Promise((resolve, reject) => {
19	    const child = spawn("npx", ["tsx", "src/cli.ts"]);
20	    let stdout = "";
21	    let stderr = "";
22	
23	    child.stdout.on("data", (chunk) => (stdout += chunk));
24	    child.stderr.on("data", (chunk) => (stderr += chunk));
25	    child.on("error", reject);
26	    child.on("close", (exitCode) => resolve({ stdout, stderr, exitCode: exitCode ?? 0 }));
27	
28	    child.stdin.write(JSON.stringify(scenario));
29	    child.stdin.end();
30	  });
31	
32	describe("claim-office CLI", () => {
33	  // "reads a scenario from stdin and writes {results}" and "quote → {premium},
34	  // claim → {payout, remainingCap}" are both asserted end to end by the schema
35	  // example below, which pins the exact output shape.
36	
37	  it("processes the schema example (amulet quote + 200 G fire claim) end to end", async () => {
38	    const scenario = {
39	      customer: { yearsWithMHPCO: 5 },
40	      steps: [
41	        {
42	          op: "quote",
43	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
44	        },
45	        {
46	          op: "claim",
47	          policy: 0,
48	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
49	        },
50	      ],
51	    };
52	
53	    const { stdout } = await runCli(scenario);
54	
55	    // quote: 60 base − 12 loyalty (5 years) + 6 initial assessment = 54, + 5 fee = 59
56	    // claim: amulet value 600 → cap 1200; 200 − 100 deductible = 100; 1200 − 100 = 1100
57	    expect(JSON.parse(stdout)).toEqual({
58	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
59	    });
60	  }, 30000);
61	
62	  it("exits with a non-zero status and writes to stderr on an unknown item type; no results on stdout", async () => {
63	    const { stdout, stderr, exitCode } = await runCli({
64	      customer: { yearsWithMHPCO: 0 },
65	      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
66	    });
67	
68	    expect(exitCode).not.toBe(0);
69	    expect(stderr).toContain("broomstick");
70	    expect(stdout).not.toContain("results");
71	  }, 30000);
72	
73	  it("reports errors as a clean message, not a raw stack trace", async () => {
74	    const { stderr } = await runCli({
75	      customer: { yearsWithMHPCO: 0 },
76	      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
77	    });
78	
79	    // The previous test is satisfied by a stack trace, since a trace contains
80	    // the message. For a JSON-in/JSON-out tool that is still bad behaviour: it
81	    // leaks absolute paths and interpreter internals and buries the one line
82	    // the user needs. This pins the message the user should actually see.
83	    expect(stderr).toContain("unknown item type: broomstick");
84	    expect(stderr).not.toMatch(/^\s+at /m);
85	    expect(stderr).not.toContain("/src/claim-office.ts");
86	    expect(stderr.trim().split("\n")).toHaveLength(1);
87	  }, 30000);
88	});
